import{_ as i,o as a,c as t,a5 as l}from"./chunks/framework.CnBNXlt7.js";const m=JSON.parse('{"title":"特性","description":"","frontmatter":{},"headers":[],"relativePath":"code/cpp/feature/index.md","filePath":"code/cpp/feature/index.md","lastUpdated":1740813955000}'),r={name:"code/cpp/feature/index.md"};function n(s,e,o,c,d,p){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h1><h2 id="c-23-有什么新特性" tabindex="-1">C++23 有什么新特性 <a class="header-anchor" href="#c-23-有什么新特性" aria-label="Permalink to &quot;C++23 有什么新特性&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Link <a href="https://en.cppreference.com/w/cpp/23" target="_blank" rel="noreferrer">cppreference</a></p><p>...etc</p></div><h2 id="c-20-有什么新特性" tabindex="-1">C++20 有什么新特性 <a class="header-anchor" href="#c-20-有什么新特性" aria-label="Permalink to &quot;C++20 有什么新特性&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Link <a href="https://en.cppreference.com/w/cpp/20" target="_blank" rel="noreferrer">cppreference</a></p><ul><li>Feature test macros</li><li>Three-way comparison operator <code>&lt;=&gt;</code> and operator==() = default</li><li>Designated initializers</li><li>Init-statements and initializers in range-for</li><li>char8_t</li><li>New attributes: [[no_unique_address]], [[likely]], [[unlikely]]</li><li>Pack-expansions in lambda init-captures</li><li>Removed the requirement to use typename to disambiguate types in many contexts</li><li>consteval, constinit</li><li>Further relaxed constexpr</li><li>Signed integers are 2&#39;s complement</li><li>Bitwise shift operators unified behavior</li><li>aggregate initialization using parentheses</li><li>coroutines</li><li>modules</li><li>Constraints and concepts</li><li>Abbreviated function template</li><li>DR11: array new can deduce array size</li></ul></div><h2 id="c-17-有什么新特性" tabindex="-1">C++17 有什么新特性 <a class="header-anchor" href="#c-17-有什么新特性" aria-label="Permalink to &quot;C++17 有什么新特性&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Link <a href="https://en.cppreference.com/w/cpp/17" target="_blank" rel="noreferrer">cppreference</a></p><p>...etc</p></div><h2 id="c-14-有什么新特性" tabindex="-1">C++14 有什么新特性 <a class="header-anchor" href="#c-14-有什么新特性" aria-label="Permalink to &quot;C++14 有什么新特性&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Link <a href="https://en.cppreference.com/w/cpp/14" target="_blank" rel="noreferrer">cppreference</a></p><ul><li>variable templates</li><li>generic lambdas</li><li>lambda init-capture</li><li>new/delete elision</li><li>relaxed restrictions on constexpr functions</li><li>binary literals</li><li>digit separators</li><li>return type deduction for functions</li><li>aggregate classes with default non-static member initializers.</li></ul></div><h2 id="c-11-有什么新特性" tabindex="-1">C++11 有什么新特性 <a class="header-anchor" href="#c-11-有什么新特性" aria-label="Permalink to &quot;C++11 有什么新特性&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Link <a href="https://en.cppreference.com/w/cpp/11" target="_blank" rel="noreferrer">cppreference</a></p><ul><li>auto and decltype</li><li>defaulted and deleted functions</li><li>final and override</li><li>trailing return type</li><li>rvalue references</li><li>move constructors and move assignment operators</li><li>scoped enums</li><li>constexpr and literal types</li><li>list initialization</li><li>delegating and inherited constructors</li><li>brace-or-equal initializers</li><li>nullptr</li><li>long long</li><li>char16_t and char32_t</li><li>type aliases</li><li>variadic templates</li><li>generalized (non-trivial) unions</li><li>generalized PODs (trivial types and standard-layout types)</li><li>Unicode string literals</li><li>user-defined literals</li><li>attributes</li><li>lambda expressions</li><li>noexcept specifier and noexcept operator</li><li>alignof and alignas</li><li>multithreaded memory model</li><li>thread-local storage</li><li>GC interface (removed in C++23)</li><li>range-for (based on a Boost library)</li><li>static_assert (based on a Boost library)</li></ul></div><h2 id="by-stroustrup" tabindex="-1">by stroustrup <a class="header-anchor" href="#by-stroustrup" aria-label="Permalink to &quot;by stroustrup&quot;">​</a></h2><details class="details custom-block"><summary>C++11 features</summary><blockquote><p>C++11 feels like a new language -- stroustrup</p></blockquote><blockquote><p><a href="https://www.stroustrup.com/hopl20main-p5-p-bfc9cd4--final.pdf" target="_blank" rel="noreferrer">page29</a></p></blockquote><p>C++11 introduced a bewildering number of language features, including:</p><ul><li>memory model - an efficient low level-model of modern hardware as a foundation for concurrency</li><li>auto and decltype - avoiding redundant repetition of type names</li><li>range-for - simple linear traversal of ranges</li><li>move semantics and rvalue references - minimizing copying of data</li><li>uniform initialization - an (almost) completely general syntax and semantics for initializing objects of all kinds and types</li><li>nullptr - a name for the null pointer</li><li>constexpr functions - compile-time evaluated functions</li><li>user-defined literals - literals for user-defined types</li><li>raw string literals - literals where escape characters are not needed, mostly for regular expressions</li><li>attributes - associating essentially arbitrary information with a name</li><li>lambdas - unnamed function objects</li><li>variadic templates - templates that can handle an arbitrary number of arguments of arbitrary types</li><li>template aliases - the ability to rename a template and to bind some template arguments for the new name</li><li>noexcept - a way of ensuring that an exception isn’t thrown from a function</li><li>override and final - explicit syntax for managing large class hierarchies</li><li>static_assert - compile-time assertions</li><li>long long - a longer integer type</li><li>default member initializers - give a data member a default value that can be superseded by initialization in a constructor</li><li>enum classes - strongly typed enumerations with scoped enumerators</li></ul><p>And here is a list of the major standard-library components:</p><ul><li>unique_ptr and shared_ptr - resource-management pointers relying on RAII</li><li>memory model and atomic variables</li><li>thread, mutex, condition_variable, etc. - type-safe and portable support for basic system- level concurrency</li><li>future, promise, and packaged_task, etc. - slightly higher-level concurrency</li><li>tuple - unnamed simple composite types</li><li>type traits - testable properties of types for use in metaprogramming</li><li>regular expression matching</li><li>random numbers - with many generators (engines) and distributions</li><li>Time - time_point and duration</li><li>unordered_map, etc. - hash tables</li><li>forward_list - a singly-linked list</li><li>array - a fixed-constant-sized array that knows its size</li><li>emplace operations - construct objects right within a container to avoid copying</li><li>exception_ptr - enables transfer of exceptions between threads</li></ul></details><details class="details custom-block"><summary>C++17 features</summary><p>C++17 had about 21 new language features (depending on how you count), including:</p><ul><li>Constructor template argument deduction - simplify object definitions</li><li>Deduction guides - an explicit notation for resolving constructor template argument deduction ambiguities</li><li>Structured bindings - simplify notation and eliminate a source of uninitialized variables</li><li>inline variables - simplify the use of statically allocated variables in header-only libraries</li><li>Fold expressions - simplify some uses of variadic templates</li><li>Explicit test in conditions - a bit like conditions in for-statements</li><li>Guaranteed copy elision - eliminate many redundant copy operations</li><li>Stricter expression evaluation order - prevents some subtle order-of-evaluation mistakes</li><li>auto as a template argument type - type deduction for value template arguments</li><li>Standard attributes to catch common mistakes - <code>[[maybe_unused]]</code>, <code>[[nodiscard]]</code>, and <code>[[fallthrough]]</code></li><li>Hexadecimal floating-point literals</li><li>Constant expression if - simplify compile-time evaluated code</li></ul><p>The C++17 standard-library added about 13 new features plus many minor modifications:</p><ul><li>optional, variant, and any - standard-library types for expressing alternatives</li><li>shared_mutex and shared_lock (reader-writer locks) and scoped_lock</li><li>parallel STL - multi-threaded and/or vectorized versions of standard-library algorithms</li><li>file system - the ability to portably manipulate file-system paths and directories</li><li>string_view - a non-owning reference to an immutable sequence of characters</li><li>Mathematical special functions - including Laguerre and Legendre polynomials, beta func- tions, Riemann zeta function</li></ul></details>',14)])])}const f=i(r,[["render",n]]);export{m as __pageData,f as default};
